  "measure_id": "CA-2026-P40",
  "restatements": [
    {
      "clause_id": "Prop 40 Preamble",
      "text": "Names the measure the 2026 Billionaire Tax Act."
    },
    {
      "clause_id": "Prop 40 Sec. 1",
      "text": "Provides the short title for the Act."
    },
    {
      "clause_id": "Prop 40 Sec. 2",
      "text": "Lists findings regarding federal funding cuts to Medi-Cal, public schools, and CalFresh, and notes the concentration of wealth among California billionaires."
    },
    {
      "clause_id": "Prop 40 Sec. 3",
      "text": "Declares the intent to fund health care, education, and food assistance through a one-time tax on billionaire wealth."
    },
    {
      "clause_id": "Prop 40 Sec. 4 §37",
      "text": "Amends the California Constitution to authorize a one-time tax on personal property and wealth of billionaires. Creates the 2026 Billionaire Tax Reserve Fund, allocating 90% to a Health Account and 10% to an Education and Food Assistance Account. Exempts these revenues from existing constitutional spending limits and formulas."
    },
    {
      "clause_id": "Prop 40 Sec. 5 §16355",
      "text": "Adds to the Government Code the procedures for the Reserve Fund. Specifies the types of health, education, and food programs that can be funded. Sets annual appropriation limits. Requires a $50 million initial loan to the Franchise Tax Board for administration. Mandates annual reporting from the Department of Finance."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50300",
      "text": "Names Part 27 of the Revenue and Taxation Code."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50301",
      "text": "Imposes a 5% excise tax for tax year 2026 on the net worth of individuals and applicable trusts with a net worth of $1 billion or more, phasing in the rate starting at $1 billion. Allows payment in five annual installments with a 7.5% deferral charge."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50302",
      "text": "Specifies which debts and liabilities may reduce net worth, explicitly excluding debts to related persons, contingent debts, and charitable pledges made after October 15, 2025."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50303",
      "text": "Establishes valuation methods for assets. Excludes real property, specific pensions, and up to $5 million in art or collectibles. Sets a formula for valuing private business interests using book value and profits unless a certified appraisal is provided."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50304",
      "text": "Creates an Optional Deferral Account (ODA) allowing taxpayers whose tax liability exceeds their publicly traded assets to defer the tax, paying a 5% tax on later withdrawals or distributions."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50305",
      "text": "Allows the Franchise Tax Board to penalize appraisers for substantial or gross overstatements or understatements of valuation in a certified appraisal."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50306",
      "text": "Apportions 100% of the tax to California for residents, while allowing alternative apportionment if a taxpayer proves the wealth was not accumulated or sustained in the state."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50307",
      "text": "Allows a pro rata credit for net wealth taxes paid to other jurisdictions."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50308",
      "text": "Defines key terms, establishing the tax obligation date as January 1, 2026, and the valuation date as December 31, 2026."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50309",
      "text": "Grants the Franchise Tax Board authority to adopt regulations and explicitly exempts the Board from the Administrative Procedure Act until January 1, 2028."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50310",
      "text": "Permits the Legislature to amend the Act by a two-thirds vote, provided the amendment is consistent with and furthers the Act's purposes."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50311",
      "text": "Includes a severability clause and instructs courts to reform dates or periods to preserve the tax if specific dates are found unconstitutional."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50312",
      "text": "Imposes penalties of 20% for substantial tax understatements and 40% for gross understatements. Codifies economic substance and step transaction doctrines to prevent tax avoidance."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50313",
      "text": "Requires the provisions to be liberally construed."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50314",
      "text": "Authorizes an expedited judicial review process through a validation action filed solely in Sacramento County Superior Court, with direct appeal to the California Supreme Court."
    },
    {
      "clause_id": "Prop 40 Sec. 7",
      "text": "Prohibits the state net worth tax from being deducted against state income taxes."
    },
    {
      "clause_id": "Prop 40 Sec. 8",
      "text": "Declares that this measure prevails over any conflicting billionaire wealth tax measure on the same ballot."
    },
    {
      "clause_id": "Prop 40 Sec. 9",
      "text": "Grants standing to the proponent and citizens to defend the Act in court if the Attorney General does not."
    }
  ],
